def transform(grid):
    h, w = len(grid), len(grid[0])
    # Separators are the most frequently occurring color among uniform full lines.
    row_colors = {r: grid[r][0] for r in range(h) if len(set(grid[r])) == 1}
    col_colors = {c: grid[0][c] for c in range(w) if len({grid[r][c] for r in range(h)}) == 1}
    divider = Counter(list(row_colors.values()) + list(col_colors.values())).most_common(1)[0][0]
    sr = [r for r, color in row_colors.items() if color == divider]
    sc = [c for c, color in col_colors.items() if color == divider]

    def spans(n, cuts):
        result, start = [], 0
        for cut in cuts:
            if cut > start:
                result.append((start, cut))
            start = cut + 1
        if start < n:
            result.append((start, n))
        return result

    rows, cols = spans(h, sr), spans(w, sc)
    freq = Counter(grid[r][c] for r in range(h) for c in range(w)
                   if r not in sr and c not in sc)
    background = freq.most_common(1)[0][0]
    marker = min((v for v in freq if v != background), key=lambda v: freq[v])
    out = [[background for _ in cols] for _ in rows]
    for i, (r0, r1) in enumerate(rows):
        for j, (c0, c1) in enumerate(cols):
            pixels = {(r, c) for r in range(r0, r1) for c in range(c0, c1)
                      if grid[r][c] == marker}
            if any((r + 1, c) in pixels or (r, c + 1) in pixels for r, c in pixels):
                out[i][j] = 1
    return out


if __name__ == '__main__':
